def E(n):
    if n < 0:
        return None
    try:
        numerator = 3 * ((n + 2)**(n + 2) if n+2 == 0 else math.factorial(n + 2) + 1)
        denominator = 2 * n - 1
        if denominator == 0:
            return None
        return numerator / denominator
    except ValueError:
        return None

import math

solutions = []
for n in range(10): # Check up to n=9
    result = E(n)
    if result is not None and result == int(result):
        solutions.append(n)

print(solutions)
